//! Submitter formNoValidate reflects boolean presence without author coercion.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://submitter-no-validate.test/send><input id=area name=q required><input id=input type=submit name=i value=I><button id=button type=submit name=b value=B>Send</button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://submitter-no-validate.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn submitter_form_no_validate_canonical_hook_free_truthiness_and_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input','button']){var x=document.getElementById(id),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formNoValidate');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get formNoValidate'||a.set.name!=='set formNoValidate'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'formNoValidate')||x.formNoValidate!==false)throw 'canonical';var calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('bool'),BigInt(1),author]){a.set.call(x,value);if(x.formNoValidate!==true||x.getAttributeNS(null,'formnovalidate')!==''||calls)throw 'true';}for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.formNoValidate!==false||x.hasAttribute('formnovalidate')||calls)throw 'false';}a.set.call(x);if(x.formNoValidate!==false||calls)throw 'missing argument';}");}
#[test]
fn submitter_form_no_validate_inert_exact_namespace_raw_presence_and_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var tag of ['input','button']){var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml',tag);x.setAttributeNS('urn:foreign','formnovalidate','foreign');x.setAttributeNS(null,'FORMNOVALIDATE','upper');if(x.formNoValidate!==false)throw 'namespace';x.setAttributeNS(null,'formnovalidate','\ud800');if(x.formNoValidate!==true)throw 'raw presence';var a=x.getAttributeNodeNS(null,'formnovalidate'),copy=x.cloneNode(false);copy.formNoValidate=false;if(copy.formNoValidate!==false||x.formNoValidate!==true||a.value!=='\ud800'||copy.getAttributeNS('urn:foreign','formnovalidate')!=='foreign')throw 'copy';x.formNoValidate=true;if(x.getAttributeNodeNS(null,'formnovalidate')!==a||a.value!=='')throw 'identity';}"#);}
#[test]
fn submitter_form_no_validate_native_required_validation_is_submitter_scoped(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let submit=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap();let l=crate::navigation::address("https://submitter-no-validate.test/source",&crate::navigation::Location::home()).unwrap();let before=f.controls.iter().map(|(&n,c)|(n,c.required,c.checked,c.value.text(),c.owner)).collect::<Vec<_>>();assert!(f.submit_request(&d,owner,Some(submit),&l,&l).is_err());run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}');x.formNoValidate=true;"));let sent=f.submit_request(&d,owner,Some(submit),&l,&l).unwrap();let crate::http::Request::FormPost{body,..}=sent.request else{panic!("POST")};assert_eq!(body,if id=="input"{b"q=&i=I".as_slice()}else{b"q=&b=B".as_slice()});assert!(f.submit_request(&d,owner,None,&l,&l).is_err());run(&mut d,&mut f,&mut p,"x.formNoValidate=false;");assert!(f.submit_request(&d,owner,Some(submit),&l,&l).is_err());assert_eq!(f.controls.iter().map(|(&n,c)|(n,c.required,c.checked,c.value.text(),c.owner)).collect::<Vec<_>>(),before);run(&mut d,&mut f,&mut p,"document.getElementById('form').noValidate=true;");assert!(f.submit_request(&d,owner,Some(submit),&l,&l).is_ok());}}

#[test]
fn submitter_form_no_validate_brands_saved_prototype_and_native_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input','button']){var x=document.getElementById(id),other=document.getElementById(id==='input'?'button':'input'),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formNoValidate');for(var bad of [{},document,document.body,document.getElementById('form'),other,Object.create(P)]){try{a.set.call(bad,true);throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}x.setAttribute('formnovalidate','legacy');var old=x.getAttributeNodeNS(null,'formnovalidate'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.formNoValidate=false;var records=watch.takeRecords();if(x.formNoValidate!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='formnovalidate')throw 'remove observation';var calls=0;x.formNoValidate={toString:function(){calls++;throw 'coercion';},valueOf:function(){calls++;throw 'coercion';}};records=watch.takeRecords();if(calls||x.formNoValidate!==true||x.getAttributeNS(null,'formnovalidate')!==''||records.length!==1||records[0].oldValue!==null)throw 'hook free observation';watch.disconnect();Object.defineProperty(P,'formNoValidate',{get:function(){return 'author';},configurable:true});a.set.call(x,false);if(x.formNoValidate!=='author'||a.get.call(x)!==false)throw 'saved authority';Object.defineProperty(P,'formNoValidate',a);}");}
#[test]
fn submitter_form_no_validate_captured_origin_denies_then_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var input=document.getElementById('input'),button=document.getElementById('button'),a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'formNoValidate'),b=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,'formNoValidate');if(a.get.call(input)!==false||b.get.call(button)!==false)throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-submitter-no-validate.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(input);","b.get.call(button);","a.set.call(input,true);","b.set.call(button,true);"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://submitter-no-validate.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"a.set.call(input,true);b.set.call(button,true);if(input.formNoValidate!==true||button.formNoValidate!==true)throw 'fresh recovery';");}
#[test]
fn submitter_form_no_validate_bounded_atomic_refusal_and_zero_copy_getter(){for id in ["input","button"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("var x=document.getElementById('{id}');x;"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_form_no_validate_set(object,&Value::Bool(true))}else{bridge.button_form_no_validate_set(object,&Value::Bool(true))};assert!(result.is_err(),"id {id} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.formNoValidate=true;if(x.formNoValidate!==true)throw 'fresh recovery';");}for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("document.getElementById('{id}');"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_form_no_validate_get(object)}else{bridge.button_form_no_validate_get(object)};assert!(result.is_err());p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_form_no_validate_get(object)}else{bridge.button_form_no_validate_get(object)};assert!(matches!(result,Ok(Value::Bool(false))));}}}
#[test]
fn submitter_form_no_validate_attribute_writers_preserve_dirty_editor(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}'),editor=document.getElementById('area');editor.value='Edited';x.formNoValidate=true;var attribute=x.getAttributeNodeNS(null,'formnovalidate'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('formnovalidate','false');","x.setAttributeNS(null,'formnovalidate','false');","attribute.value='false';","attribute.nodeValue='false';","attribute.textContent='false';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.formNoValidate=true;watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.formNoValidate!==true||x.getAttributeNodeNS(null,'formnovalidate')!==attribute||records.length!==1||records[0].oldValue!==''||records[0].attributeName!=='formnovalidate'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.required),(3,1,2,true,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('formnovalidate');replacement.value='\ud800';x.setAttributeNodeNS(replacement);if(x.formNoValidate!==true||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'raw replacement';x.formNoValidate=false;if(x.formNoValidate!==false||replacement.ownerElement!==null)throw 'remove';"#);}}
